import json
d = json.load(open('/root/distill_sparse_swiglu/artifacts/snr_extended_results.json'))

# Compact: no per_layer, no loss_curve
out = {
    'experiment': d['experiment'],
    'config': d['config'],
    'kl_snapshots': {},
    'bce_snapshots': {},
    'summary': d['summary']
}
for step, snap in d['kl']['snapshots'].items():
    out['kl_snapshots'][step] = {k: v for k, v in snap.items() if k != 'per_layer'}
for step, snap in d['bce']['snapshots'].items():
    out['bce_snapshots'][step] = {k: v for k, v in snap.items() if k != 'per_layer'}

# Per-layer as separate key
out['kl_per_layer'] = {}
for step, snap in d['kl']['snapshots'].items():
    out['kl_per_layer'][step] = snap['per_layer']
out['bce_per_layer'] = {}
for step, snap in d['bce']['snapshots'].items():
    out['bce_per_layer'][step] = snap['per_layer']

# Loss curves
out['kl_loss_curve'] = d['kl']['loss_curve']
out['bce_loss_curve'] = d['bce']['loss_curve']
out['kl_time_s'] = d['kl']['time_s']
out['bce_time_s'] = d['bce']['time_s']

json.dump(out, open('/tmp/snr_full_reorg.json', 'w'), indent=2)

# Print compact snapshot summary
compact = {'kl': out['kl_snapshots'], 'bce': out['bce_snapshots'], 'summary': out['summary']}
print(json.dumps(compact, indent=2))
